// Define constants
const int MAX_STEPS = 100;
const float MIN_DIST = 0.001;
const float MAX_DIST = 100.0;
const float BAILOUT = 1.9;
const float POWER = 8.0;



const int uFractalType = 0; // 0 = Mandlebulb, 1 = Julia, 2 = broken, 3 = Burning Ship

// Rotation function around the Y-axis
vec3 rotateY(vec3 p, float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return vec3(
        c * p.x - s * p.z,
        p.y,
        s * p.x + c * p.z
    );
}

// Function to calculate the distance to the Mandelbulb
float mandelbulb(vec3 p) {
    vec3 z = p;
    float dr = 1.0;
    float r = 0.0;

    // Apply rotation to the internal geometry
    float angle = iTime * 0.1; // Rotate over time
    z = rotateY(z, angle);

    for (int i = 0; i < 100; i++) {
        r = length(z);
        if (r > BAILOUT) break; // Use bailout condition

        // Convert to polar coordinates
        float theta = acos(z.z / r);
        float phi = atan(z.y, z.x);
        dr = pow(r, POWER - 1.0) * POWER * dr + 1.0;

        // Scale and rotate the point
        float zr = pow(r, POWER);
        theta = theta * POWER;
        phi = phi * POWER;

        // Convert back to Cartesian coordinates
        z = zr * vec3(sin(theta) * cos(phi), sin(phi) * sin(theta), cos(theta));
        z += p;
    }
    return 0.5 * log(r) * r / dr;
}

// Function to calculate the distance to the Julia set
float julia(vec3 p) {
    vec3 z = p;
    vec3 c = vec3(0.355, 0.955, 0.355);
    float dr = 1.0;
    float r = 0.0;

    // Apply  rotation
    float angle = iTime * 0.2 + length(p.xy) * 0.5; // Rotate over time with a different factor
    z = rotateY(z, angle);

    for (int i = 0; i < 100; i++) {
        r = length(z);
        if (r > BAILOUT) break;

        // Convert to polar coordinates
        float theta = acos(z.z / r);
        float phi = atan(z.y, z.x);
        dr = pow(r, POWER - 1.0) * POWER * dr + 1.0;

        // Scale and rotate the point
        float zr = pow(r, POWER);
        theta = theta * POWER;
        phi = phi * POWER;

        // Convert back to Cartesian coordinates
        z = zr * vec3(sin(theta) * cos(phi), sin(phi) * sin(theta), cos(theta));
        z += c;
    }
    return 0.5 * log(r) * r / dr;
}
// Function to calculate the distance to the Menger Sponge
float mengerSponge(vec3 p) {
    float scale = 3.0;
    float angle = iTime * 0.1; // Rotate over time
    p = rotateY(p, angle);

    for (int i = 0; i < MAX_STEPS; i++) {
        p = abs(p);
        if (p.x < p.y) p.xy = p.yx;
        if (p.x < p.z) p.xz = p.zx;
        if (p.y < p.z) p.yz = p.zy;
        p = p * scale - vec3(scale - 1.0);
    }
    return length(p) * pow(scale, float(-MAX_STEPS));
}

// Function to calculate the distance to the Burning Ship fractal
float burningShip(vec3 p) {
    vec3 z = p;
    float dr = 1.0;
    float r = 0.0;

    // Apply rotation 
    float angle = iTime * 0.1; // Rotate over time
    z = rotateY(z, angle);

    for (int i = 0; i < 100; i++) {
        r = length(z);
        if (r > BAILOUT) break;

        // Convert to polar coordinates
        float theta = acos(z.z / r);
        float phi = atan(z.y, z.x);
        dr = pow(r, POWER - 1.0) * POWER * dr + 1.0;

        // Scale and rotate the point
        float zr = pow(r, POWER);
        theta = theta * POWER;
        phi = phi * POWER;

        // Convert back to Cartesian coordinates
        z = zr * vec3(sin(theta) * cos(phi), sin(phi) * sin(theta), cos(theta));
        z = abs(z); // Burning Ship specific transformation
        z += p;
    }
    return 0.5 * log(r) * r / dr;
}

// Function to calculate the normal at a point on the fractal
vec3 calculateNormal(vec3 p) {
    float epsilon = 0.001;
    vec3 e = vec3(epsilon, 0.0, 0.0);
    float d;
    if (uFractalType == 0) d = mandelbulb(p);
    else if (uFractalType == 1) d = julia(p);
    else if (uFractalType == 2) d = mengerSponge(p);
    else d = burningShip(p);

    vec3 n = vec3(
        (uFractalType == 0) ? mandelbulb(p + e.xyy) - d : (uFractalType == 1) ? julia(p + e.xyy) - d : (uFractalType == 2) ? mengerSponge(p + e.xyy) - d : burningShip(p + e.xyy) - d,
        (uFractalType == 0) ? mandelbulb(p + e.yxy) - d : (uFractalType == 1) ? julia(p + e.yxy) - d : (uFractalType == 2) ? mengerSponge(p + e.yxy) - d : burningShip(p + e.yxy) - d,
        (uFractalType == 0) ? mandelbulb(p + e.yyx) - d : (uFractalType == 1) ? julia(p + e.yyx) - d : (uFractalType == 2) ? mengerSponge(p + e.yyx) - d : burningShip(p + e.yyx) - d
    );
    return normalize(n);
}

// Function to calculate the Phong lighting
vec3 phongLighting(vec3 p, vec3 rd, vec3 lightPos) {
    vec3 normal = calculateNormal(p);
    vec3 lightDir = normalize(lightPos - p);
    vec3 viewDir = normalize(-rd);

    // Diffuse component
    float diff = max(dot(normal, lightDir), 0.0);

    // Specular component
    vec3 reflectDir = reflect(-lightDir, normal);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

    // Combine results
    vec3 ambient = vec3(0.1);
    vec3 diffuse = vec3(0.8) * diff;
    vec3 specular = vec3(0.5) * spec;
    return ambient + diffuse + specular;
}

// Raymarching function
float raymarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        float d;
        if (uFractalType == 0) d = mandelbulb(p);
        else if (uFractalType == 1) d = julia(p);
        else if (uFractalType == 2) d = mengerSponge(p);
        else d = burningShip(p);

        if (d < MIN_DIST) return t;
        t += d;
        if (t > MAX_DIST) break;
    }
    return MAX_DIST;
}

// Main function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;


    float zoom = 1.0 + ((iMouse.y*0.5) / iResolution.y) * 3.0; 

    vec3 ro = vec3(0.0, 0.0, zoom); 
    vec3 rd = normalize(vec3(uv, -1.0));

    float t = raymarch(ro, rd);
    vec3 hitPoint = ro + t * rd;

    vec3 color = vec3(0.0);
    if (t < MAX_DIST) {
        vec3 lightPos = vec3(5.0, 5.0, 5.0); // Position of the light source
        color = phongLighting(hitPoint, rd, lightPos);

        // Add color
        float timeColor = 0.5 + 0.5 * sin(iTime + length(hitPoint));
        color *= vec3(timeColor, 1.0 - timeColor, 0.5 + 0.5 * timeColor);
    }

    fragColor = vec4(color, 1.0);
}
